@using sv_d94254903ea34fd5bd57b688cb703a6c.Services
@inject ISettingsService SettingsService

<div class="section-panel">
    <h4 class="section-title">Profile</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading profile…</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-area">
                <img src="@_avatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label text-muted">@_avatarUrl</span>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" class="form-control" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea class="form-control" rows="3" @bind="_bio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
                    Discard Changes
                </button>
            </div>

            @if (_toastMessage is not null)
            {
                <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                    @_toastMessage
                </div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Snapshot for discard
    private UserProfile? _saved;

    private string? _toastMessage;
    private bool _toastIsError;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        ApplyProfile(profile);
        _saved = profile;
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toastMessage = null;
        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _saved = profile;
            _toastMessage = "Profile saved successfully!";
            _toastIsError = false;
        }
        catch (Exception ex)
        {
            _toastMessage = $"Error: {ex.Message}";
            _toastIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_saved is not null)
            ApplyProfile(_saved);
        _toastMessage = null;
    }
}

