{"file_text": "@using sv_d94254903ea34fd5bd57b688cb703a6c.Services
@inject ISettingsService SettingsService

<div class="section-panel">
    <h4 class="section-title">Security</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading security settings…</p>
    }
    else
    {
        @* Change Password *@
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <span>🔑 Change Password</span>
                <span class="chevron">@(_passwordExpanded ? "▲" : "▼")</span>
            </button>

            @if (_passwordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label>Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label>New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label>Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary btn-sm" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating…" : "Update Password")
                    </button>
                    @if (_passwordMessage is not null)
                    {
                        <div class="toast-message @(_passwordIsError ? "toast-error" : "toast-success")">
                            @_passwordMessage
                        </div>
                    }
                </div>
            }
        </div>

        @* Two-Factor Authentication *@
        <div class="tfa-row">
            <div>
                <strong>Two-Factor Authentication</strong>
                <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="switch">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="slider"></span>
            </label>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="text-muted last-changed">
                Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        @* Active Sessions *@
        <h5 class="subsection-title">Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-sm sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != _currentSessionId)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @* Revoke confirmation dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="confirm-overlay" @onclick="CancelRevoke">
                <div class="confirm-dialog" @onclick:stopPropagation>
                    <p>Revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                    <div class="confirm-actions">
                        <button class="btn btn-danger btn-sm" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                            @(_revoking ? "Revoking…" : "Revoke")
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke" disabled="@_revoking">
                            Cancel
                        </button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private bool _loading = true;

    // Password
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordMessage;
    private bool _passwordIsError;

    // 2FA
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;

    // Sessions
    private List<ActiveSession> _sessions = [];
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // Treat the first session as "current" for demo purposes
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = [.. settings.Sessions];
        if (_sessions.Count > 0)
            _currentSessionId = _sessions[0].Id;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordIsError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "New password and confirmation do not match.";
            _passwordIsError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordIsError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _lastPasswordChange = DateTime.UtcNow;
        }
        catch (Exception ex)
        {
            _passwordMessage = ex.Message;
            _passwordIsError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
        _revoking = false;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
