toolArgs.file_text:
@using sv_d94254903ea34fd5bd57b688cb703a6c.Services
@inject ISettingsService SettingsService

<div class="section-panel">
    <h4 class="section-title">Notifications</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading preferences…</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" class="form-check-input" @bind="_emailNotifications" />
            </label>
            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" class="form-check-input" @bind="_pushNotifications" />
            </label>
            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" class="form-check-input" @bind="_weeklyDigest" />
            </label>
        </div>

        <h5 class="subsection-title">Muted Channels</h5>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="channel-row">
                    <input type="checkbox" class="form-check-input"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <span>#@channel</span>
                </label>
            }
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Preferences")
            </button>
        </div>

        @if (_toastMessage is not null)
        {
            <div class="toast-message toast-success">@_toastMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];

    private readonly string[] _allChannels = ["general", "announcements", "random", "engineering", "design", "support"];

    private string? _toastMessage;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toastMessage = null;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _toastMessage = "Preferences saved!";
        _saving = false;
    }
}

