toolArgs.file_text:
.section-panel {
    max-width: 720px;
}

.section-title {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.chevron {
    font-size: 0.8rem;
    color: #888;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

.form-group {
    margin-bottom: 0.85rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.88rem;
}

.tfa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
    margin-bottom: 0.5rem;
}

.status-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-size: 0.78rem;
    font-weight: 600;
    margin-left: 0.5rem;
}

.status-on {
    background: #d1e7dd;
    color: #0f5132;
}

.status-off {
    background: #f8d7da;
    color: #842029;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    border-radius: 24px;
    transition: 0.25s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    border-radius: 50%;
    transition: 0.25s;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

.last-changed {
    font-size: 0.85rem;
    margin-bottom: 1.5rem;
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.sessions-table {
    font-size: 0.9rem;
}

/* Confirmation overlay */
.confirm-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.confirm-dialog {
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 380px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
}

.confirm-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

.toast-message {
    margin-top: 0.75rem;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    font-size: 0.85rem;
    font-weight: 500;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
}

