@using sv_d94254903ea34fd5bd57b688cb703a6c.Services
@inject ISettingsService SettingsService

<div class="section-panel">
    <h4 class="section-title">Appearance</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        @* Theme *@
        <div class="option-group">
            <label class="group-label">Theme</label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-option @(_theme == theme ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        @theme
                    </label>
                }
            </div>
        </div>

        @* Font Size *@
        <div class="option-group">
            <label class="group-label">Font Size</label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-option @(_fontSize == size ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        @size
                    </label>
                }
            </div>
        </div>

        @* Language *@
        <div class="option-group">
            <label class="group-label">Language</label>
            <select class="form-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        @* Compact Mode *@
        <div class="option-group toggle-row">
            <label class="group-label">Compact Mode</label>
            <label class="switch">
                <input type="checkbox" @bind="_compactMode" />
                <span class="slider-track"></span>
            </label>
        </div>

        @* Live Preview *@
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-label">Live Preview</div>
            <div class="preview-card">
                <h5>Dashboard</h5>
                <p>This is a preview of how your content will look with the selected settings.</p>
                <button class="preview-btn">Action Button</button>
            </div>
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>
        </div>

        @if (_toastMessage is not null)
        {
            <div class="toast-message toast-success">@_toastMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toastMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _toastMessage = "Appearance saved!";
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}

