toolArgs.file_text:
.section-panel {
    max-width: 640px;
}

.section-title {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.option-group {
    margin-bottom: 1.25rem;
}

.group-label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    font-size: 0.9rem;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.45rem 0.9rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: border-color 0.15s, background 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 500;
}

.radio-option input[type="radio"] {
    display: none;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider-track {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    border-radius: 24px;
    transition: 0.25s;
}

.slider-track::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    border-radius: 50%;
    transition: 0.25s;
}

.switch input:checked + .slider-track {
    background-color: #0d6efd;
}

.switch input:checked + .slider-track::before {
    transform: translateX(20px);
}

/* Live Preview */
.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.25rem;
    margin: 1.5rem 0;
    transition: all 0.25s;
}

.preview-label {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #888;
    margin-bottom: 0.75rem;
}

.preview-card h5 {
    margin-bottom: 0.4rem;
}

.preview-card p {
    margin-bottom: 0.75rem;
}

.preview-btn {
    padding: 0.35rem 0.9rem;
    border-radius: 4px;
    border: none;
    font-size: 0.85rem;
    cursor: pointer;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-btn {
    background: #0d6efd;
    color: white;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-label {
    color: #999;
